    // Accepts either a bare WeatherObserved (key-values) or the UDP protocol envelope
// {"kind":"reading","payload":{...WeatherObserved}} so both encodings work.
const MAX_LIVE_AGE_MS = 10000;   // older observations are rolling-window replays
const MAX_FUTURE_MS = 5000;      // tolerated clock skew
const now = Date.now();
const nodeFromTopic = msg.topic.split('/')[2];

const reject = (reason) => {
    node.status({ fill: 'red', shape: 'ring', text: `${nodeFromTopic}: ${reason}` });
    return [null, { topic: msg.topic, payload: { nodeId: nodeFromTopic, reason, raw: String(msg.payload).slice(0, 300) } }];
};

let data;
try {
    data = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    return reject('invalid JSON');
}
const envelope = data && data.kind === 'reading' ? data : null;
const wo = envelope ? data.payload : data;

if (!wo || typeof wo !== 'object') return reject('empty payload');
if (wo.type !== 'WeatherObserved') return reject('type is not WeatherObserved');
if (typeof wo.id !== 'string' || !wo.id.startsWith('urn:ngsi-ld:WeatherObserved:')) return reject('invalid id');
if (typeof wo.temperature !== 'number' || !Number.isFinite(wo.temperature)) return reject('invalid temperature');
if (typeof wo.relativeHumidity !== 'number' || wo.relativeHumidity < 0 || wo.relativeHumidity > 1) {
    return reject('relativeHumidity must be a fraction in [0,1]');
}
const observed = Date.parse(wo.dateObserved);
if (Number.isNaN(observed)) return reject('invalid dateObserved');

// Duplicate suppression: QoS 1 redelivery and rolling-window replays reuse the same id.
const seen = context.get('seen') || [];
if (seen.includes(wo.id)) {
    node.status({ fill: 'yellow', shape: 'dot', text: `duplicate ${wo.id.split(':').pop()}` });
    return [null, null];
}
seen.push(wo.id);
if (seen.length > 1000) seen.splice(0, seen.length - 1000);
context.set('seen', seen);

const synced = (envelope ? envelope.timeSynchronized : wo.timeSynchronized) !== false;
const skewed = observed - now > MAX_FUTURE_MS;
// Untrusted clocks: fall back to reception time.
const t = synced && !skewed ? observed : now;
const live = now - t <= MAX_LIVE_AGE_MS;
const nodeId = (wo.refDevice || '').replace('urn:ngsi-ld:Device:', '') || nodeFromTopic;

node.status({ fill: live ? 'green' : 'blue', shape: 'dot', text: `${nodeId} ${wo.temperature}°C ${live ? 'live' : 'replay'}` });
return [{
    topic: nodeId,
    payload: {
        nodeId,
        temperature: wo.temperature,
        humidity: Math.round(wo.relativeHumidity * 1000) / 10,   // percent
        observedAt: t,
        receivedAt: now,
        live,
        timeTrusted: synced && !skewed
    }
}, null];

    // Latest live reading per node; a node only counts towards the average while fresh.
const STALE_MS = 5000;
const latest = context.get('latest') || {};
const now = Date.now();

if (msg.topic !== 'tick') {
    const r = msg.payload;
    const series = r.live ? r.nodeId : `${r.nodeId} (buffered)`;
    if (r.live) {
        latest[r.nodeId] = r;
        context.set('latest', latest);
    }
    // Per-node history points at observation time (replays fill in the gaps).
    return [null, null,
        { topic: series, payload: { x: r.observedAt, y: r.temperature } },
        { topic: series, payload: { x: r.observedAt, y: r.humidity } },
        null];
}

const fresh = Object.values(latest).filter((r) => now - r.receivedAt <= STALE_MS);
if (fresh.length === 0) {
    node.status({ fill: 'grey', shape: 'ring', text: 'no live nodes' });
    return [null, null, null, null, { payload: 'No live data' }];
}
const avg = (k) => Math.round(fresh.reduce((s, r) => s + r[k], 0) / fresh.length * 10) / 10;
const t = avg('temperature');
const h = avg('humidity');
node.status({ fill: 'green', shape: 'dot', text: `${t}°C ${h}% (${fresh.length} nodes)` });
return [
    { payload: t },
    { payload: h },
    { topic: 'average', payload: { x: now, y: t } },
    { topic: 'average', payload: { x: now, y: h } },
    { payload: `${fresh.length} node(s): ${fresh.map((r) => r.nodeId).sort().join(', ')}` }
];

// Combines MQTT Last-Will status ("online"/"offline", retained) with a data
// watchdog: a sensor node that is "online" but silent for STALE_MS is STALE.
// Output 1 feeds the topology diagram, output 2 the state-change popups.
const STALE_MS = 5000;
// The alert-server heartbeat is published every 5 s (--status-interval); allow a few misses.
const SERVER_STALE_MS = 15000;
const EXPECTED = env.get('EXPECTED_COMPONENTS') || 'esp32-001,esp32-002,alert-server';
const comps = context.get('comps') || {};
const now = Date.now();
const get = (id) => (comps[id] = comps[id] || { connection: 'unknown', lastData: 0, state: '' });

EXPECTED.split(',').map((s) => s.trim()).filter(Boolean).forEach(get);

if (msg.topic === 'tick') {
    // fall through to evaluation
} else if (msg.topic.endsWith('/heartbeat')) {
    // alert-server heartbeat: its "last data" is the time of the last heartbeat
    const id = msg.topic.split('/')[2];
    get(id).lastData = now;
    if (get(id).connection === 'unknown') get(id).connection = 'online';
} else if (msg.topic.endsWith('/status')) {
    const id = msg.topic.split('/')[2];
    if (id === 'command-centre') return null;
    get(id).connection = String(msg.payload).trim().toLowerCase() === 'online' ? 'online' : 'offline';
} else if (msg.payload && msg.payload.nodeId) {
    get(msg.payload.nodeId).lastData = msg.payload.receivedAt;
    if (msg.payload.live && get(msg.payload.nodeId).connection === 'unknown') {
        get(msg.payload.nodeId).connection = 'online';
    }
}

const notifications = [];
const components = Object.keys(comps).sort().map((id) => {
    const c = comps[id];
    const isSensor = id !== 'alert-server';
    const staleMs = isSensor ? STALE_MS : SERVER_STALE_MS;
    const age = c.lastData ? now - c.lastData : null;
    let state = 'OK';
    if (c.connection === 'offline') state = 'OFFLINE';
    else if (age === null || age > staleMs) state = c.lastData ? 'STALE' : 'NO DATA';
    else if (c.connection === 'unknown') state = 'UNKNOWN';
    if (c.state && c.state !== state && (state === 'OFFLINE' || state === 'STALE' || c.state === 'OFFLINE' || c.state === 'STALE')) {
        notifications.push({ payload: `${id}: ${c.state} → ${state}` });
    }
    c.state = state;
    return {
        id,
        kind: isSensor ? 'sensor' : 'server',
        connection: c.connection,
        lastData: age === null ? null : `${Math.round(age / 1000)} s ago`,
        ageMs: age,
        state
    };
});
context.set('comps', comps);

const bad = components.filter((r) => r.state !== 'OK').length;
node.status({ fill: bad ? 'red' : 'green', shape: 'dot', text: bad ? `${bad} component(s) degraded` : 'all OK' });
return [{
    payload: {
        components,
        broker: flow.get('brokerState') || 'Connecting…',
        ccHost: env.get('CC_HOST') || '192.168.50.2 · cc.comcs.lan',
        brokerPort: env.get('MQTT_PORT') || '1883'
    }
}, notifications.length ? notifications : null];

// Status events from the mqtt-in nodes: green = connected, red = disconnected, yellow = connecting.
// Stored in flow context; "Component health" picks it up on the next 1 s tick.
const fill = msg.status && msg.status.fill;
const text = fill === 'green' ? 'Connected' : fill === 'yellow' ? 'Connecting…' : 'DISCONNECTED';
flow.set('brokerState', text);
return null;

// Alert log for the dashboard panel. Input: Smart Data Model "Alert" (key-values) on
// comcs/cell1/alerts, or {topic:'ack', payload:{id}} / {topic:'ack-all'} from the panel.
// Outputs: [popup, alerts panel].
const MAX_ALERTS = 1000;
let alerts = context.get('alerts') || [];

const panel = () => ({ payload: { alerts, unacked: alerts.filter(a => !a.acked).length } });
const showStatus = () => {
    const unacked = alerts.filter(a => !a.acked).length;
    node.status(unacked
        ? { fill: 'red', shape: 'dot', text: `${unacked} unacked of ${alerts.length}` }
        : { fill: 'green', shape: 'dot', text: `all acknowledged (${alerts.length})` });
};

if (msg.topic === 'ack' || msg.topic === 'ack-all') {
    const id = msg.topic === 'ack' && msg.payload && typeof msg.payload === 'object' ? msg.payload.id : null;
    const now = new Date().toISOString();
    for (const a of alerts) {
        if (!a.acked && (id === null || a.id === id)) {
            a.acked = true;
            a.ackedAt = now;
        }
    }
    context.set('alerts', alerts);
    showStatus();
    return [null, panel()];
}

let a;
try {
    a = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    a = { description: String(msg.payload) };
}
if (!a || typeof a !== 'object') a = { description: String(a) };

// Deduplicate QoS 1 redeliveries and resent readings by Alert id.
const ids = context.get('ids') || [];
if (a.id && ids.includes(a.id)) return null;
if (a.id) { ids.push(a.id); if (ids.length > 2 * MAX_ALERTS) ids.shift(); context.set('ids', ids); }

const issued = a.dateIssued && !isNaN(new Date(a.dateIssued)) ? a.dateIssued : new Date().toISOString();
const row = {
    id: a.id || `local:${Date.now()}:${Math.random().toString(36).slice(2, 8)}`,
    issued,
    severity: String(a.severity || 'unknown').toLowerCase(),
    category: a.subCategory || a.category || '',
    description: a.description || JSON.stringify(a).slice(0, 200),
    source: (a.alertSource || '').replace('urn:ngsi-ld:Device:', ''),
    acked: false
};
alerts.unshift(row);
if (alerts.length > MAX_ALERTS) alerts.length = MAX_ALERTS;
context.set('alerts', alerts);
showStatus();

return [
    { payload: `⚠ [${row.severity}] ${row.description}` },
    panel()
];

    // Publishes WeatherObserved key-values for two nodes with a slowly drifting value.
const seq = (context.get('seq') || 0) + 1;
context.set('seq', seq);
const base = 22 + 2 * Math.sin(seq / 60);
const now = new Date().toISOString().replace(/\.\d+Z$/, 'Z');
const mk = (nodeId, dt, dh) => ({
    topic: `comcs/cell1/${nodeId}/weather`,
    qos: 1,
    payload: JSON.stringify({
        id: `urn:ngsi-ld:WeatherObserved:${nodeId}:sim:${seq}`,
        type: 'WeatherObserved',
        dateObserved: now,
        location: { type: 'Point', coordinates: [-8.608, 41.178] },
        refDevice: `urn:ngsi-ld:Device:${nodeId}`,
        temperature: Math.round((base + dt + Math.random() * 0.4) * 10) / 10,
        relativeHumidity: Math.round((0.5 + dh + Math.random() * 0.02) * 100) / 100
    })
});
return [[mk('esp32-001', 0, 0), mk('esp32-002', 0.8, 0.03)]];

    const now = new Date().toISOString().replace(/\.\d+Z$/, 'Z');
return { topic: 'comcs/cell1/alerts', qos: 1, payload: JSON.stringify({
    id: `urn:ngsi-ld:Alert:cell1:sim:${Date.now()}`,
    type: 'Alert',
    category: 'environment',
    subCategory: 'temperatureDifferential',
    severity: 'medium',
    dateIssued: now,
    description: 'Temperature differential 2.6 °C between esp32-001 and esp32-002 exceeds 2 °C',
    alertSource: 'urn:ngsi-ld:Device:alert-server',
    data: { differential: 2.6, threshold: 2, nodes: ['esp32-001', 'esp32-002'] }
}) };

    const old = new Date(Date.now() - 120000).toISOString().replace(/\.\d+Z$/, 'Z');
return { topic: 'comcs/cell1/esp32-001/weather', qos: 1, payload: JSON.stringify({
    id: `urn:ngsi-ld:WeatherObserved:esp32-001:replay:${Date.now()}`, type: 'WeatherObserved', dateObserved: old,
    location: { type: 'Point', coordinates: [-8.608, 41.178] }, refDevice: 'urn:ngsi-ld:Device:esp32-001',
    temperature: 21.7, relativeHumidity: 0.49
}) };
